--- 初始化头像信息
---@param index integer 角色战场id
---@param playerCardId integer @ 卡牌id
---@param newCardExpInfo table 卡牌经验信息 {cardLevel = v.cardLevel, cardExp = v.cardExp}
function BattleEndHeadNode:ShowHeadNode(index, playerCardId, teamId, cardExpInfo, showType)
    -- 初始化头像信息
    local cardDojo
    local inBattle = not isNull(UIBattlingTools)    -- 战斗外扫荡的时候没有UIBattlingTools
    if inBattle then
        cardDojo = UIBattlingTools:GetCardInfo(index, playerCardId, teamId)
    else
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        cardDojo = cardComponent:GetCardById(checkInt(playerCardId))
    end

    self.LT_HeadNode:FreshNode(cardDojo, true, nil)
    self.LT_HeadNode:SetButtonState(false)

    -- 初始化等级信息
    self.star = checkInt(cardDojo.star)
    local oldLv = checkInt(cardDojo.cardLevel)
    local oldExp = checkInt(cardDojo.cardExp)
    if not isNull(cardExpInfo) then
        oldLv = cardExpInfo.oldExp.cardLevel
        oldExp = cardExpInfo.oldExp.cardExp
    end

    ---@type CardStarVo
    local starInfo  = cardConfMgr:GetCardStarInfo(cardDojo.cardId, self.star)
    self.maxLevel = cardConfMgr:GetCardMaxLevel(cardDojo.advanceLevel)
    local isMaxLv = oldLv >= self.maxLevel
    isMaxLv = false     -- 这个版本不显示max，直接显示等级

    local rt_tmp = self.LT_HeadNode.LvValueTMP
    local txtComp = rt_tmp:GetComponent(typeof(TextMeshProUGUI))
    txtComp.text = isMaxLv and "Max" or string.format(self:GetLevelTextFormat(oldLv), oldLv)
    
    -- 初始化稀有度
    ---@type CardVo
    local cardVo  = cardConfMgr:GetCardByRefId(cardDojo.cardId)
    self.rare = cardVo.rare     -- vo里面是配表的初始稀有度，dojo里面是会升阶的真实稀有度。升级经验按初始稀有度走
    
    -- 如果升级信息是空的
    if isNull(cardExpInfo) then
        -- 直接设置等级和经验
        local expData = self:GetCardNextLevelExpData(oldLv)
        local lastTotal = expData.totalExp - expData.exp
        local showExp = oldExp - lastTotal
        local showProgress = showExp / expData.exp
        -- print("[结算] 卡牌头像 设置等级 ", isMaxLv, oldLv, oldExp)
        self.LT_Slider2:SetProgress(showProgress)
        txtComp.text = isMaxLv and "Max" or string.format(self:GetLevelTextFormat(oldLv), oldLv)
        if playerCardId < 0 then
            -- 机器人不显示经验条
            KTool.SetActive(self.LT_Slider2.controller.gameObject, false)
        end
    else
        -- 表演升级
        local newExp = cardExpInfo.newExp.cardExp
        local newLv = cardExpInfo.newExp.cardLevel
        
        local expInfo = {
            oldLv = oldLv,
            newLv = newLv,
            oldExp = oldExp,
            newExp = newExp,
        }
        -- print("[结算] 卡牌头像 升级 ", table.dump(expInfo))
    
        -- checkInt 防止空报错
        expInfo.newLv = checkInt(expInfo.newLv)
        expInfo.oldLv = checkInt(expInfo.oldLv)
        expInfo.newExp = checkInt(expInfo.newExp)
        expInfo.oldExp = checkInt(expInfo.oldExp)
    
        local rt_tmp = self.LT_HeadNode.LvValueTMP
        local txtComp = rt_tmp:GetComponent(typeof(TextMeshProUGUI))
        if showType == PanelShowType.Animate then
            -- 升级动画
            UICommonUtils.AnimateUpgrade(expInfo, Bind(self, self.GetCardNextLevelExpData),
                QuickUpgradeTime, NormalUpgradeTime, 0.3, txtComp, Bind(self, self.GetLevelTextFormat), nil, self.LT_Slider2, self.coGroup)
        elseif showType == PanelShowType.Direct then
            local expData = self:GetCardNextLevelExpData(expInfo.newLv)
            local lastTotal = expData.totalExp - expData.exp
            local showExp = expInfo.newExp - lastTotal
            local showProgress = showExp / expData.exp
            self.LT_Slider2:SetProgress(showProgress)
            txtComp.text = isMaxLv and "Max" or string.format(self:GetLevelTextFormat(expInfo.newLv), expInfo.newLv)
        end
        
        -- 打开升级标签
        local isUpGrade = expInfo.newLv > expInfo.oldLv
        KTool.SetActive(self.RT_UpSign.gameObject, isUpGrade)
    end
end

function BattleEndHeadNode:StopAnimateShowHeadNode()
    if not isNull(self.coGroup.co) then
        cs_coroutine.stop(self.coGroup.co)
        self.coGroup.co = nil
    end
    self.LT_Slider2:StopLerpProgress()
    if not isNull(self.coGroup.tweener) then
        self.coGroup.tweener:Complete()
        self.coGroup.tweener = nil
    end
end

function BattleEndHeadNode:GetCardNextLevelExpData(fromLv)
    return cardConfMgr:GetCardExp(math.min(fromLv + 1, self.maxLevel), self.rare, self.maxLevel)
end

function BattleEndHeadNode:GetLevelTextFormat(lv)
    return lv > 0 and lv <= 9 and "0%d" or "%d"
end
------------------------------------------------Function

return BattleEndHeadNode
